import{_ as o,a0 as a,w as d,s as p,I as l,x as e,a1 as u,A as i,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Ubuntu 中如何安装或升级 Linux 内核到4.2 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 中如何安装或升级 Linux 内核到4.2 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 中如何安装或升级 Linux 内核到4.2 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 中如何安装或升级 Linux 内核到4.2 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150901 How to Install or Upgrade to Linux Kernel 4.2 in Ubuntu","title":"在 Ubuntu 中如何安装或升级 Linux 内核到4.2","tag":"201509","desc":""},"relativePath":"201509/20150901 How to Install or Upgrade to Linux Kernel 4.2 in Ubuntu.md","filePath":"[post].md"}'),x={name:"201509/20150901 How to Install or Upgrade to Linux Kernel 4.2 in Ubuntu.md"};function s(b,n,m,g,k,_){const t=a("Link");return d(),p("div",null,[n[20]||(n[20]=l("h1",{id:"在-ubuntu-中如何安装或升级-linux-内核到4-2",tabindex:"-1"},[e("在 Ubuntu 中如何安装或升级 Linux 内核到4.2 "),l("a",{class:"header-anchor",href:"#在-ubuntu-中如何安装或升级-linux-内核到4-2","aria-label":"Permalink to “在 Ubuntu 中如何安装或升级 Linux 内核到4.2”"},"​")],-1)),n[21]||(n[21]=l("p",null,[l("img",{src:"http://ubuntuhandbook.org/wp-content/uploads/2014/12/linux-kernel-icon-tux.png",alt:""})],-1)),l("p",null,[n[1]||(n[1]=e("Linux 内核 4.2已经发布了。Linus Torvalds 在 ",-1)),u(t,{href:"https://lkml.org/lkml/2015/8/30/96"},{default:i(()=>[...n[0]||(n[0]=[e("lkml.org",-1)])]),_:1}),n[2]||(n[2]=e(" 上写到:",-1))]),n[22]||(n[22]=r('<blockquote><p>通过这周这么小的变动，看来在最后一周 发布 4.2 版本应该不会有问题，当然还有几个修正，但是看起来也并不需要延迟一周。 所以这就到了，而且 4.3 的合并窗口现已打开。我已经有了几个等待处理的合并请求，明天我开始处理它们，然后在适当的时候放出来。 从 rc8 以来的简短日志很小，已经附加。这个补丁也很小...</p></blockquote><h3 id="新内核-4-2-有哪些改进" tabindex="-1">新内核 4.2 有哪些改进？: <a class="header-anchor" href="#新内核-4-2-有哪些改进" aria-label="Permalink to “新内核 4.2 有哪些改进？:”">​</a></h3><ul><li>重写英特尔的x86汇编代码</li><li>支持新的 ARM 板和 SoC</li><li>对 F2FS 的 per-file 加密</li><li>AMDGPU 的内核 DRM 驱动程序</li><li>对 Radeon DRM 驱动的 VCE1 视频编码支持</li><li>初步支持英特尔的 Broxton Atom SoC</li><li>支持 ARCv2 和 HS38 CPU 内核</li><li>增加了队列自旋锁的支持</li><li>许多其他的改进和驱动更新。</li></ul><h3 id="在-ubuntu-中如何下载4-2内核" tabindex="-1">在 Ubuntu 中如何下载4.2内核 : <a class="header-anchor" href="#在-ubuntu-中如何下载4-2内核" aria-label="Permalink to “在 Ubuntu 中如何下载4.2内核 :”">​</a></h3><p>此内核版本的二进制包可供下载链接如下：</p>',5)),l("ul",null,[l("li",null,[u(t,{href:"https://lkml.org/lkml/2015/8/30/96"},{default:i(()=>[...n[3]||(n[3]=[e("下载 4.2 内核(.DEB)",-1)])]),_:1})])]),n[23]||(n[23]=r(`<p>首先检查你的操作系统类型，32位（i386）的或64位(amd64)的，然后使用下面的方式依次下载并安装软件包：</p><ol><li>linux-headers-4.2.0-xxx_all.deb</li><li>linux-headers-4.2.0-xxx-generic_xxx_i386/amd64.deb</li><li>linux-image-4.2.0-xxx-generic_xxx_i386/amd64.deb</li></ol><p>安装内核后，在终端（(Ctrl+Alt+T)）运行<code>sudo update-grub</code>命令来更新 grub boot-loader。</p><p>如果你需要一个低延迟系统（例如用于录制音频），请下载并安装下面的包：</p><ol><li>linux-headers-4.2.0_xxx_all.deb</li><li>linux-headers-4.2.0-xxx-lowlatency_xxx_i386/amd64.deb</li><li>linux-image-4.2.0-xxx-lowlatency_xxx_i386/amd64.deb</li></ol><p>对于没有图形用户界面的 Ubuntu 服务器，你可以运行下面的命令通过 wget 来逐一抓下载，并通过 dpkg 来安装：</p><p>对于64位的系统请运行:</p><pre><code>cd /tmp/

wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.2-unstable/linux-headers-4.2.0-040200_4.2.0-040200.201508301530_all.deb

wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.2-unstable/linux-headers-4.2.0-040200-generic_4.2.0-040200.201508301530_amd64.deb

wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.2-unstable/linux-image-4.2.0-040200-generic_4.2.0-040200.201508301530_amd64.deb

sudo dpkg -i linux-headers-4.2.0-*.deb linux-image-4.2.0-*.deb
</code></pre><p>对于32位的系统,请运行:</p><pre><code>cd /tmp/

wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.2-unstable/linux-headers-4.2.0-040200_4.2.0-040200.201508301530_all.deb

wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.2-unstable/linux-headers-4.2.0-040200-generic_4.2.0-040200.201508301530_i386.deb

wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.2-unstable/linux-image-4.2.0-040200-generic_4.2.0-040200.201508301530_i386.deb

sudo dpkg -i linux-headers-4.2.0-*.deb linux-image-4.2.0-*.deb
</code></pre><p>最后，重新启动计算机才能生效。</p>`,11)),l("p",null,[n[5]||(n[5]=e("要恢复或删除旧的内核，请参阅",-1)),u(t,{href:"http://ubuntuhandbook.org/index.php/2015/08/install-latest-kernel-script/"},{default:i(()=>[...n[4]||(n[4]=[e("通过脚本安装内核",-1)])]),_:1}),n[6]||(n[6]=e("。",-1))]),n[24]||(n[24]=l("hr",null,null,-1)),l("p",null,[n[8]||(n[8]=e("via: ",-1)),u(t,{href:"http://ubuntuhandbook.org/index.php/2015/08/upgrade-kernel-4-2-ubuntu/"},{default:i(()=>[...n[7]||(n[7]=[e("http://ubuntuhandbook.org/index.php/2015/08/upgrade-kernel-4-2-ubuntu/",-1)])]),_:1})]),l("p",null,[n[12]||(n[12]=e("作者：",-1)),u(t,{href:"http://ubuntuhandbook.org/index.php/about/"},{default:i(()=>[...n[9]||(n[9]=[e("Ji m",-1)])]),_:1}),n[13]||(n[13]=e(" 译者：",-1)),u(t,{href:"https://github.com/strugglingyouth"},{default:i(()=>[...n[10]||(n[10]=[e("strugglingyouth",-1)])]),_:1}),n[14]||(n[14]=e(" 校对：",-1)),u(t,{href:"https://github.com/wxy"},{default:i(()=>[...n[11]||(n[11]=[e("wxy",-1)])]),_:1})]),l("p",null,[n[17]||(n[17]=e("本文由 ",-1)),u(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...n[15]||(n[15]=[e("LCTT",-1)])]),_:1}),n[18]||(n[18]=e(" 原创编译，",-1)),u(t,{href:"https://linux.cn/"},{default:i(()=>[...n[16]||(n[16]=[e("Linux中国",-1)])]),_:1}),n[19]||(n[19]=e(" 荣誉推出",-1))])])}const L=o(x,[["render",s]]);export{C as __pageData,L as default};
